    display: grid;
    grid-template-columns: 1fr 1fr;
    min-height: 80vh;
    align-items: center;
    background: var(--color-surface);
}

.hero-content {
    padding: var(--spacing-lg) 0;
    max-width: 500px;
}

.hero-eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.2em;
    font-size: 0.8rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.hero-heading {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: var(--spacing-md);
}

.hero-description {
    font-size: 1.1rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
}

.hero-actions {
    display: flex;
    gap: var(--spacing-sm);
}

.hero-image-container {
    height: 100%;
}

.hero-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Featured Products */
.featured-products {
    padding: var(--spacing-xl) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-lg);
}

.section-header h2 {
    font-size: 2rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--color-text);
    padding-bottom: 4px;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-md);
}

.product-card {
    transition: var(--transition);
}

.product-image {
    aspect-ratio: 3/4;
    overflow: hidden;
    background: var(--color-surface);
    margin-bottom: var(--spacing-sm);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1rem;
    margin-bottom: 4px;
}

.product-price {
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
}

/* Deals */
.deals {
    padding-bottom: var(--spacing-xl);
}

.deals-banner {
    background: #f0f0f0;
    padding: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-radius: var(--border-radius);
}

.deals-content {
    max-width: 500px;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-sm);
}

.deals-content p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-text-muted);
}

.deals-badge {
    background: white;
    padding: var(--spacing-md);
    border-radius: 50%;
    width: 150px;
    height: 150px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.deals-badge span {
    font-size: 0.8rem;
    text-transform: uppercase;
}

.deals-badge strong {
    font-size: 1.5rem;
    color: #e74c3c;
}

/* Editorial */
.editorial {
    padding: var(--spacing-xl) 0;
    background: var(--color-surface);
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
}

.editorial-text p {
    margin-bottom: var(--spacing-sm);
    font-size: 1.1rem;
    color: var(--color-text-muted);
}

.link-more {
    display: inline-block;
    margin-top: var(--spacing-md);
    font-weight: 600;
    text-decoration: underline;
}

/* Footer */
.site-footer {
    background: #1a1a1a;
    color: white;
    padding: var(--spacing-xl) 0 var(--spacing-md);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-brand p {
    margin-top: var(--spacing-sm);
    color: #999;
    max-width: 250px;
}

.footer-nav h3,
.footer-newsletter h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: var(--spacing-md);
}

.footer-nav ul li {
    margin-bottom: var(--spacing-xs);
}

.footer-nav a {
    color: #999;
    font-size: 0.9rem;
}

.footer-nav a:hover {
    color: white;
}

.footer-newsletter p {
    color: #999;
    font-size: 0.9rem;
    margin-bottom: var(--spacing-sm);
}

.newsletter-form {
    display: flex;
    gap: 8px;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    background: #333;
    border: none;
    color: white;
    border-radius: var(--border-radius);
}

.footer-bottom {
    border-top: 1px solid #333;
    padding-top: var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.footer-bottom p {
    font-size: 0.8rem;
    color: #666;
}

.social-links {
    display: flex;
    gap: var(--spacing-sm);
}

.social-links a {
    color: #999;
}

.social-links a:hover {
    color: white;
}

/* Mobile Responsive */
@media (max-width: 992px) {
    .hero {
        grid-template-columns: 1fr;
    }
    .hero-image-container {
        order: -1;
        height: 400px;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .editorial-grid {
        grid-template-columns: 1fr;
    }
    .nav-list {
        display: none; /* In a real app, I'd implement a mobile menu */
    }
    .header-inner {
        height: 60px;
    }
    .hero-heading {
        font-size: 2.5rem;
    }
}

/* Accessibility: Focus */
*:focus-visible {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

.sr-only:focus {
    /* For accessibility skip links and other elements */
}
