', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/shopping-home-page--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s3/style.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents=':root {
    --color-bg: #ffffff;
    --color-text: #1a1a1a;
    --color-text-muted: #666666;
    --color-primary: #1a1a1a;
    --color-accent: #3498db;
    --color-border: #e0e0e0;
    --color-surface: #f8f9fa;
    --container-width: 1200px;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 4rem;
    --spacing-xl: 6rem;
    --border-radius: 4px;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
    line-height: 1.6;
    color: var(--color-text);
    background-color: var(--color-bg);
    overflow-x: hidden;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: inherit;
    text-decoration: none;
}

ul {
    list-style: none;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 var(--spacing-sm);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header */
.site-header {
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(5px);
}

.header-inner {
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo-text {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 0.1em;
}

.nav-list {
    display: flex;
    gap: var(--spacing-md);
}

.nav-list a {
    font-weight: 500;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-text-muted);
    transition: var(--transition);
}

.nav-list a:hover,
.nav-list a[aria-current="page"] {
    color: var(--color-text);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
}

.search-form {
    display: flex;
    align-items: center;
    border: 1px solid var(--color-border);
    border-radius: 20px;
    padding: 4px 12px;
    transition: var(--transition);
}

.search-form:focus-within {
    border-color: var(--color-text);
}

.search-input {
    border: none;
    outline: none;
    padding: 4px;
    font-size: 0.9rem;
    width: 120px;
    background: transparent;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--color-text);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4px;
    position: relative;
    transition: var(--transition);
}

.icon-button:hover {
    color: var(--color-accent);
}

.cart-count {
    position: absolute;
    top: -2px;
    right: -2px;
    background: var(--color-accent);
    color: white;
    font-size: 0.7rem;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Buttons */
.button {
    display: inline-block;
    padding: 0.8rem 2rem;
    font-size: 0.9rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    cursor: pointer;
    transition: var(--transition);
    border-radius: var(--border-radius);
    text-align: center;
    border: 1px solid transparent;
}

.button-primary {
    background: var(--color-primary);
    color: white;
}

.button-primary:hover {
    background: #333;
}

.button-secondary {
    background: transparent;
    color: var(--color-text);
    border-color: var(--color-text);
}

.button-secondary:hover {
    background: var(--color-text);
    color: white;
}

.button-outline {
    background: transparent;
    border-color: var(--color-border);
    color: var(--color-text);
}

.button-outline:hover {
    border-color: var(--color-text);
}

.button-dark {
    background: var(--color-text);
    color: white;
}

.full-width {
    width: 100%;
}

/* Hero */
.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    min-height: 80vh;
    align-items: center;
    background: var(--color-surface);
}

.hero-content {
    padding: var(--spacing-lg) 0;
    max-width: 500px;
}

.hero-eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.2em;
    font-size: 0.8rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.hero-heading {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: var(--spacing-md);
}

.hero-description {
    font-size: 1.1rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
}

.hero-actions {
    display: flex;
    gap: var(--spacing-sm);
}

.hero-image-container {
    height: 100%;
}

.hero-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Featured Products */
.featured-products {
    padding: var(--spacing-xl) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-lg);
}

.section-header h2 {
    font-size: 2rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--color-text);
    padding-bottom: 4px;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-md);
}

.product-card {
    transition: var(--transition);
}

.product-image {
    aspect-ratio: 3/4;
    overflow: hidden;
    background: var(--color-surface);
    margin-bottom: var(--spacing-sm);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1rem;
    margin-bottom: 4px;
}

.product-price {
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
}

/* Deals */
.deals {
    padding-bottom: var(--spacing-xl);
}

.deals-banner {
    background: #f0f0f0;
    padding: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-radius: var(--border-radius);
}

.deals-content {
    max-width: 500px;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-sm);
}

.deals-content p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-text-muted);
}

.deals-badge {
    background: white;
    padding: var(--spacing-md);
    border-radius: 50%;
    width: 150px;
    height: 150px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
}

.deals-badge span {
    font-size: 0.8rem;
    text-transform: uppercase;
}

.deals-badge strong {
    font-size: 1.5rem;
    color: #e74c3c;
}

/* Editorial */
.editorial {
    padding: var(--spacing-xl) 0;
    background: var(--color-surface);
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
}

.editorial-text p {
    margin-bottom: var(--spacing-sm);
    font-size: 1.1rem;
    color: var(--color-text-muted);
}

.link-more {
    display: inline-block;
    margin-top: var(--spacing-md);
    font-weight: 600;
    text-decoration: underline;
}

/* Footer */
.site-footer {
    background: #1a1a1a;
    color: white;
    padding: var(--spacing-xl) 0 var(--spacing-md);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
