    margin-bottom: var(--spacing-xs);
}

.footer-nav a {
    color: #999;
    font-size: 0.9rem;
}

.footer-nav a:hover {
    color: white;
}

.footer-newsletter p {
    color: #999;
    font-size: 0.9rem;
    margin-bottom: var(--spacing-sm);
}

.newsletter-form {
    display: flex;
    gap: 8px;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    background: #333;
    border: none;
    color: white;
    border-radius: var(--border-radius);
}

.footer-bottom {
    border-top: 1px solid #333;
    padding-top: var(--spacing-md);
