    justify-content: space-between;
    align-items: center;
}

.footer-bottom p {
    font-size: 0.8rem;
    color: #666;
}

.social-links {
    display: flex;
    gap: var(--spacing-sm);
}

.social-links a {
    color: #999;
}

.social-links a:hover {
    color: white;
