            // Visual feedback
            const originalText = button.textContent;
            button.textContent = 'Added!';
            button.classList.add('button-success');

            setTimeout(() => {
                button.textContent = originalText;
                button.classList.remove('button-success');
            }, 2000);
        });
    });

