835. document.addEventListener('DOMContentLoaded', () => {
836.     // Mobile Menu Toggle
837.     const menuToggle = document.querySelector('.menu-toggle');
838.     const navList = document.querySelector('.nav-list');
839.     const announcementRegion = document.getElementById('announcement-region');
840. 
841.     if (menuToggle && navList) {
842.         menuToggle.addEventListener('click', () => {
843.             const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
844.             menuToggle.setAttribute('aria-expanded', !isExpanded);
845.             navList.classList.toggle('active');
846.         });
847.     }
848. 
849.     // Cart Functionality (Mockup)
850.     const cartButton = document.querySelector('.cart-button');
851.     const cartCount = document.querySelector('.cart-count');
852.     const addToCartButtons = document.querySelectorAll('.product-card .button');
853.     let count = 0;
854. 
855.     addToCartButtons.forEach(button => {
856.         button.addEventListener('click', () => {
857.             count++;
858.             cartCount.textContent = count;
859.             
860.             // Update accessible name for cart button
861.             cartButton.setAttribute('aria-label', `View shopping cart, ${count} item${count === 1 ? '' : 's'}`);
862.             
863.             // Announce to screen readers
864.             const productTitle = button.closest('.product-card').querySelector('.product-title').textContent;
865.             announcementRegion.textContent = `${productTitle} added to cart. Total items: ${count}.`;
866.             
867.             // Visual feedback
868.             const originalText = button.textContent;
869.             button.textContent = 'Added!';
870.             button.classList.add('button-success');
871.             
872.             setTimeout(() => {
873.                 button.textContent = originalText;
874.                 button.classList.remove('button-success');
875.             }, 2000);
876.         });
877.     });
