     margin-bottom: var(--spacing-sm);
 }

 .hero-heading {
     font-size: 3.5rem;
     line-height: 1.1;
     margin-bottom: var(--spacing-md);
 }

 .hero-description {
     font-size: 1.1rem;
     color: var(--color-text-muted);
     margin-bottom: var(--spacing-lg);
 }

 .hero-actions {
     display: flex;
     gap: var(--spacing-sm);
 }

 .hero-image-container {
     height: 100%;
 }

 .hero-image {
     width: 100%;
     height: 100%;
     object-fit: cover;
 }

 /* Featured Products */
 .featured-products {
     padding: var(--spacing-xl) 0;
 }

 .section-header {
     display: flex;
     justify-content: space-between;
     align-items: flex-end;
     margin-bottom: var(--spacing-lg);
 }

 .section-header h2 {
     font-size: 2rem;
 }

 .view-all {
