     transform: scale(1.05);
 }

 .product-info h3 {
     font-size: 1rem;
     margin-bottom: 4px;
 }

 .product-price {
     font-weight: 700;
     margin-bottom: var(--spacing-sm);
 }

 /* Deals */
 .deals {
     padding-bottom: var(--spacing-xl);
 }

 .deals-banner {
